/**
 * generated by stackra gen from desktop/wiring.ts, runway.yaml
 * (environments.dev.desktop, release.desktop.feedPath, environments.<env>.desktop.channel) and the
 * root runway.yaml (feed.publicOrigin) — do not edit
 * Purpose: the Electron main-process entry of the desktop target: single instance (a second launch
 *          hands its arguments to the first and exits before it registers anything), the privileged
 *          `app://` scheme, then the app built from the main-process wiring (its derived root
 *          module stands in for the module file the console does not write): its menus, the bridges
 *          the installed packages ship, the desktop and CSP config, and the hardening baseline.
 * Boundary: the baseline is not configurable (context isolation, sandbox, no node integration, web
 *           security, no webview, the CSP header, navigation and window-open guards, permission
 *           handlers, fuses; ADR 0251 d3). The bridge handler accepts calls from `app://bundle/`
 *           only, and from the Vite dev origin only in an unpackaged build. The update feed is
 *           derived from the root feed origin, the member's feed path and the environment's
 *           channel.
 * Runtime: node
 */
import { app as electron, protocol } from "electron";
import { createApp } from "@stackra/app/electron";
import { devPorts, updateFeed } from "@stackra/runway/ports";
import { mainWiring } from "../desktop/wiring";

/** Boots main once; a second instance quits and stops here, so it never races the first. */
async function start(): Promise<void> {
  if (!electron.requestSingleInstanceLock()) {
    electron.quit(); // the first instance receives this launch's argv through `second-instance`
    return;
  }
  protocol.registerSchemesAsPrivileged([
    { scheme: "app", privileges: { standard: true, secure: true, supportFetchAPI: true } },
  ]); // never bypassCSP

  /**
   * `null` when packaged; in dev the member runway's port, remote-debug and PKCE loopback ports
   * via ports.json.
   */
  const dev = electron.isPackaged ? null : devPorts("console");

  /** `DesktopApp`: `start()` and its `windows`. */
  const desktop = await createApp({
    wiring: mainWiring, // main-process bindings only: menus, package bridges, peripherals, files
    bridgeSenders: dev ? ["app://bundle/", `${new URL(dev.url).origin}/`] : ["app://bundle/"],
    rendererDir: new URL("../renderer/", import.meta.url), // served as app://bundle/
    preload: new URL("./preload.cjs", import.meta.url),
    dev: dev && { url: dev.url, ...dev.desktop },
    updateFeed: updateFeed("console"), // <feed.publicOrigin>/<release.desktop.feedPath>/<channel>/
  });
  await desktop.start();
}

await start();
